class ConfiguratorFailure(Exception):
    pass


class RmodDetectionTimeout(Exception):
    pass


class SignatureFailure(Exception):
    pass


class SynchronizationFailure(Exception):
    pass


class ModuleActiveFailure(Exception):
    pass


class OperationStateException(Exception):
    pass


class UploadException(Exception):
    pass


class ValidateException(Exception):
    pass


class ActivateException(Exception):
    pass


class ResetException(Exception):
    pass


class HostAvailable(Exception):
    """Raised when the host is still available after an operation that should have made it unavailable."""

    def __init__(self, host: str, remote_host: str):
        super().__init__(f"Host {host} on {remote_host} is still available.")


class HostUnavailable(Exception):
    """Raised when the host is still unavailable after an operation that should have made it available."""

    def __init__(self, host: str, remote_host: str):
        super().__init__(f"Host {host} on {remote_host} is still unavailable.")


class HostSSHUnavailable(Exception):
    """Raised when the SSH connection to the host is unavailable."""

    def __init__(self, host: str, remote_host: str):
        super().__init__(f"SSH connection to host {host} on {remote_host} is unavailable.")


class ConnectionFailure(Exception):
    pass
